def find_golomb(n, max_length):
    marks = [0]
    diffs = set()

    def backtrack():
        if len(marks) == n:
            return True
        start = marks[-1] + 1
        # Try marks from start to max_length
        for next_mark in range(start, max_length + 1):
            new_diffs = []
            valid = True
            for m in marks:
                d = next_mark - m
                if d in diffs:
                    valid = False
                    break
                new_diffs.append(d)
            if valid:
                marks.append(next_mark)
                diffs.update(new_diffs)
                if backtrack():
                    return True
                marks.pop()
                for d in new_diffs:
                    diffs.remove(d)
        return False

    if backtrack():
        return marks
    else:
        return None

